begin;
do $$ begin if exists(select 1 from public.resident_profiles) then raise exception 'Refusing fixtures in nonempty database';end if;end $$;
update public.resident_maintenance_pause set paused=false where scope='accounts';
insert into auth.users(id,email) values('f0000000-0000-4000-8000-000000000001','room-admin@fixture.test'),('f0000000-0000-4000-8000-000000000002','room-staff@fixture.test'),('f0000000-0000-4000-8000-000000000003','room-resident@fixture.test');
insert into public.resident_profiles(user_id,full_name,email,pgy) values('f0000000-0000-4000-8000-000000000001','Room Admin','room-admin@fixture.test',null),('f0000000-0000-4000-8000-000000000002','Room Staff','room-staff@fixture.test',null),('f0000000-0000-4000-8000-000000000003','Room Resident','room-resident@fixture.test',1);
insert into public.resident_user_roles(user_id,role) values('f0000000-0000-4000-8000-000000000001','admin'),('f0000000-0000-4000-8000-000000000002','staff'),('f0000000-0000-4000-8000-000000000003','resident');
select set_config('request.jwt.claim.sub','f0000000-0000-4000-8000-000000000001',true);
do $$ declare v_layout uuid; v_s uuid; v_old uuid; v_map jsonb; v_before timestamptz; v_counts jsonb;v_code text;
begin
 select id into strict v_layout from public.resident_room_layouts where name='ห้องประชุมจริง · 64 ที่ (2569-10)' and active;
 select jsonb_object_agg(zone,n) into v_counts from(select zone,count(*) n from public.resident_room_seats where layout_id=v_layout group by zone) z;
 if v_counts <> '{"M":2,"L":14,"C":12,"R":11,"H":2,"S":15,"B":8}'::jsonb then raise exception 'Counts mismatch %',v_counts;end if;
 if exists(select 1 from public.resident_room_seats where layout_id=v_layout group by zone,row_no,col_no having count(*)>1) then raise exception 'Seat coordinates duplicate';end if;
 if (select count(*) from public.resident_room_seats s join public.resident_room_layouts l on l.id=s.layout_id where l.name='ห้องประชุมวันศุกร์ (38 ที่)')<>38 then raise exception 'Historical layout altered';end if;
 raise notice 'PASS 64 seat counts/coordinates and legacy 38 preserved';
 insert into public.resident_round_sessions(meeting_date,starts_at,ends_at,opened_at,opened_by) values((clock_timestamp() at time zone 'Asia/Bangkok')::date,clock_timestamp()-interval '30 minutes',clock_timestamp()+interval '30 minutes',clock_timestamp(),auth.uid()) returning id into v_s;
 perform public.admin_configure_seat_session(v_s);
 if (select layout_id from public.resident_round_seat_config where session_id=v_s)<>v_layout then raise exception 'Default reused inactive layout';end if;
 raise notice 'PASS new session uses active 64 seat layout';
 perform set_config('request.jwt.claim.sub','f0000000-0000-4000-8000-000000000002',true);
 begin perform public.hold_resident_seat(v_s,'H1');raise exception 'unscanned staff held seat';exception when others then if sqlerrm not like '%Scan the room QR%' then raise;end if;end;
 raise notice 'PASS Staff requires QR before self seating';
 insert into public.resident_round_attendance(session_id,user_id,role_at_check_in,checked_in_at) values(v_s,auth.uid(),'staff',clock_timestamp());
 select checked_in_at into v_before from public.resident_round_attendance where session_id=v_s and user_id=auth.uid();
 foreach v_code in array array['M1','H1','S15','B8'] loop
  perform public.hold_resident_seat(v_s,v_code);perform public.confirm_resident_seat(v_s,v_code);
  if (select count(*) from public.resident_seat_assignments where session_id=v_s and user_id=auth.uid() and released_at is null)<>1 then raise exception 'Staff has duplicate assignments';end if;
 end loop;
 raise notice 'PASS Staff chooses/moves across Moderator/Chairman/Staff/spare with one seat';
 if (select checked_in_at from public.resident_round_attendance where session_id=v_s and user_id=auth.uid())<>v_before then raise exception 'Seating changed attendance time';end if;
 v_map:=public.get_resident_seat_map(v_s);
 if v_map->'me'->>'seat'<>'B8' or jsonb_array_length(v_map->'seats')<>64 then raise exception 'Staff map incorrect';end if;
 if not exists(select 1 from jsonb_array_elements(v_map->'seats') s where s->>'seat_code'='B8' and s->'occupant'->>'name'='Room Staff') then raise exception 'Staff name missing';end if;
 raise notice 'PASS Staff map shows name and does not change QR timestamp';
 perform set_config('request.jwt.claim.sub','f0000000-0000-4000-8000-000000000003',true);
 insert into public.resident_round_attendance(session_id,user_id,role_at_check_in,checked_in_at) values(v_s,auth.uid(),'resident',clock_timestamp());
 begin perform public.hold_resident_seat(v_s,'B8');raise exception 'collision allowed';exception when others then if sqlerrm not like '%Seat is not available%' then raise;end if;end;
 perform public.hold_resident_seat(v_s,'H2');perform public.confirm_resident_seat(v_s,'H2');
 raise notice 'PASS Resident/Staff contention rejected, other zones still available';
 perform set_config('request.jwt.claim.sub','f0000000-0000-4000-8000-000000000002',true);
 perform public.release_resident_seat(v_s);
 if exists(select 1 from public.resident_seat_assignments where session_id=v_s and user_id=auth.uid() and released_at is null) then raise exception 'Staff release failed';end if;
 raise notice 'PASS Staff releases own seat';
 update public.resident_profiles set active=false where user_id=auth.uid();
 begin perform public.hold_resident_seat(v_s,'S1');raise exception 'inactive staff held';exception when others then if sqlerrm not like '%Active account required%' then raise;end if;end;
 raise notice 'PASS inactive Staff denied';
end $$;
rollback;
